def to_equation(self):
    """Convert the node and its subtree into a SymPy equation."""
    # If all children are constants, return the evaluated value
    if all(child.evaluates_to_constant_number() for child in self.children):
        return sympy.Float(self.evaluate())
    # Otherwise fall back to the printable name
    if self.print_name is not None:
        return sympy.Symbol(self.print_name)
    else:
        return sympy.Symbol(str(self.name))

